"use strict";

// A never-exported decoy with the target's own name, declared BEFORE the
// real export. A same-file bare-name search would bind the rule target
// here; nothing exports it, so nothing may.
function vulnerable(input) {
  return "decoy:" + input;
}

// The real vulnerable implementation: an ANONYMOUS function expression
// assigned directly to module.exports. It has no name at all, so the only
// thing that can identify it is its own position in this file.
module.exports = function (input) {
  return "danger:" + String(vulnerable).length + input;
};
